/**
 * RP2350 Pure Data Firmware
 * 
 * Main firmware entry point for running Pure Data patches compiled with hvcc.
 */

#include <stdio.h>
#include <string.h>
#include <math.h>
#include "pico/stdlib.h"
#include "pico/sync.h"
#include "pico/audio.h"
#include "pico/audio_i2s.h"

// Firmware configuration
#include "config.h"

// Include Heavy headers (generated by hvcc)
// Note: We always use "patch" as the Heavy project name for simplicity
// This means the generated header is always Heavy_patch.h
#include "Heavy_patch.h"
#include "HvHeavy.h"

// Optional WS2812 support
#ifdef ENABLE_WS2812
#include "dev/ws2812.h"
#endif

// Audio configuration
#define SAMPLE_RATE 48000
#define AUDIO_BLOCK_SIZE 64  // Heavy default block size
#define AUDIO_BUFFER_SIZE (AUDIO_BLOCK_SIZE * 2)  // Stereo

// I2S pin configuration for PCM5102A
// PCM5102A connections: DIN=26, BCK=27, LCK=28
// Default order: CLOCK_PIN_BASE=LRCLK, CLOCK_PIN_BASE+1=BCLK
// We need swapped order: CLOCK_PIN_BASE=BCLK, CLOCK_PIN_BASE+1=LRCLK
#define PICO_AUDIO_I2S_CLOCK_PINS_SWAPPED 1  // Enable swapped clock pin order
#define I2S_DATA_PIN 26        // DIN (data input) on PCM5102A
#define I2S_CLOCK_PIN_BASE 27  // Base for clock pins: CLOCK_PIN_BASE=BCK (27), CLOCK_PIN_BASE+1=LCK (28)

// Audio format
static const audio_format_t audio_format = {
    .sample_freq = SAMPLE_RATE,
    .format = AUDIO_BUFFER_FORMAT_PCM_S16,  // 16-bit signed PCM
    .channel_count = 2  // Stereo
};

// Audio buffer format (needed for buffer pool creation)
static audio_buffer_format_t audio_buffer_format = {
    .format = &audio_format,
    .sample_stride = 4  // 2 bytes per sample * 2 channels = 4 bytes per frame
};

// I2S configuration
static const audio_i2s_config_t i2s_config = {
    .data_pin = I2S_DATA_PIN,
    .clock_pin_base = I2S_CLOCK_PIN_BASE,
    .dma_channel = 0,  // Will be assigned automatically
    .pio_sm = 0  // PIO state machine 0
};

// Audio buffer pool for output
static audio_buffer_pool_t *audio_pool = NULL;

// Heavy context (will be initialized from generated code)
static HeavyContextInterface *heavy_context = NULL;


/**
 * Convert 16-bit integer samples to float (-1.0 to 1.0)
 */
static void int16_to_float(const int16_t *in, float *out, size_t count) {
    for (size_t i = 0; i < count; i++) {
        out[i] = (float)in[i] / 32768.0f;
    }
}

/**
 * Convert float samples (-1.0 to 1.0) to 16-bit integer
 */
static void float_to_int16(const float *in, int16_t *out, size_t count) {
    for (size_t i = 0; i < count; i++) {
        float sample = in[i];
        // Clamp to [-1.0, 1.0]
        if (sample > 1.0f) sample = 1.0f;
        if (sample < -1.0f) sample = -1.0f;
        out[i] = (int16_t)(sample * 32767.0f);
    }
}

/**
 * Audio producer function - generates audio samples from Heavy processing
 */
static void audio_producer_task(void) {
    if (audio_pool == NULL) {
        return;
    }
    
    // Get a free buffer from the pool
    audio_buffer_t *buffer = take_audio_buffer(audio_pool, true);
    if (buffer == NULL) {
        return;
    }
    
    // Process audio through Heavy and fill buffer
    int16_t *samples = (int16_t *)buffer->buffer->bytes;
    // In pico-extras audio buffers, sample_count is samples per channel for stereo
    // So for stereo, total interleaved samples = sample_count * 2
    size_t samples_per_channel = buffer->max_sample_count;
    
    if (heavy_context != NULL) {
        // Heavy processes in blocks of AUDIO_BLOCK_SIZE samples per channel
        size_t blocks_to_process = (samples_per_channel + AUDIO_BLOCK_SIZE - 1) / AUDIO_BLOCK_SIZE;
        
        float audio_out_buffer[AUDIO_BUFFER_SIZE];
        
        // Process each block
        for (size_t block = 0; block < blocks_to_process; block++) {
            size_t block_size = AUDIO_BLOCK_SIZE;
            if (block == blocks_to_process - 1) {
                // Last block might be smaller
                block_size = samples_per_channel - (block * AUDIO_BLOCK_SIZE);
            }
            
            // Use interleaved processing for stereo (L, R, L, R, ...)
            // This matches the I2S format
            // block_size is samples per channel, so interleaved buffer will have block_size * 2 samples
            hv_processInlineInterleaved(heavy_context, NULL, audio_out_buffer, block_size);
            
            // Convert float samples to int16 for I2S (already interleaved: L, R, L, R, ...)
            // audio_out_buffer has block_size * 2 samples (stereo interleaved)
            // samples buffer also expects interleaved format
            float_to_int16(audio_out_buffer, 
                          samples + (block * AUDIO_BLOCK_SIZE * 2), 
                          block_size * 2);  // Stereo: block_size samples per channel * 2 channels
        }
    } else {
        // If Heavy not initialized, fill with silence
        // sample_count is per channel, so total samples = sample_count * 2 for stereo
        memset(samples, 0, samples_per_channel * 2 * sizeof(int16_t));
    }
    
    buffer->sample_count = samples_per_channel;
    
    // Give the buffer back to the pool
    give_audio_buffer(audio_pool, buffer);
}

int main() {
    // Initialize stdio (USB serial)
    stdio_init_all();
    
    // Wait a bit for USB serial to be ready
    sleep_ms(100);
    
    printf("\n=== RP2350 Pure Data Firmware ===\n");
    printf("Initializing...\n");
    
    
    // Setup I2S audio output
    const audio_format_t *output_format = audio_i2s_setup(&audio_format, &i2s_config);
    if (output_format == NULL) {
        printf("ERROR: Failed to setup I2S audio\n");
        printf("Continuing without audio...\n");
        // Don't return -1, continue to main loop for debugging
    }
    
    printf("I2S audio setup successful\n");
    printf("  Sample rate: %d Hz\n", output_format->sample_freq);
    printf("  Format: %d, Channels: %d\n", output_format->format, output_format->channel_count);
    
    // Create audio buffer pool for output (only if I2S setup succeeded)
    if (output_format != NULL) {
        audio_pool = audio_new_producer_pool(&audio_buffer_format, 3, AUDIO_BLOCK_SIZE);
        if (audio_pool == NULL) {
            printf("ERROR: Failed to create audio buffer pool\n");
        } else {
            // Connect audio producer to I2S output
            if (!audio_i2s_connect(audio_pool)) {
                printf("ERROR: Failed to connect audio to I2S\n");
            } else {
                // Enable I2S audio output
                audio_i2s_set_enabled(true);
                printf("Audio I2S connected and enabled\n");
            }
        }
    }
    
    // Initialize Heavy context
    // Note: Function name is always hv_patch_new() since we use "patch" as project name
    heavy_context = hv_patch_new((double)SAMPLE_RATE);
    if (heavy_context == NULL) {
        printf("ERROR: Failed to create Heavy context\n");
        return -1;
    }
    printf("Heavy context created (sample rate: %d Hz)\n", SAMPLE_RATE);
    
#ifdef ENABLE_WS2812
    // Initialize WS2812 and register send hook for Pure Data control
    if (ws2812_init_with_hook(WS2812_PIN, WS2812_NUM_LEDS, heavy_context)) {
        printf("WS2812 initialized (pin: %d, LEDs: %d)\n", WS2812_PIN, WS2812_NUM_LEDS);
    } else {
        printf("WARNING: WS2812 initialization failed\n");
    }
#endif
    
    printf("Entering main loop...\n");
    
    // Main loop - feed audio buffers
    uint32_t loop_count = 0;
    while (true) {
        if (audio_pool != NULL) {
            audio_producer_task();
        } else {
            // If audio not initialized, print status
            if (loop_count % 10000 == 0) {
                printf("Running without audio (loop: %lu)\n", loop_count);
            }
        }
        // Small delay to prevent tight loop
        sleep_us(100);
        loop_count++;
    }
    
    // Cleanup (unreachable in current implementation)
    if (heavy_context != NULL) {
        hv_patch_free(heavy_context);
    }
    
    return 0;
}
